observation.query:
SELECT DISTINCT ?graph ?subject ?predicate ?object
WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_574be2f837968be2>
    <urn:graphragprov:unit:u_7cee9ea88431fdd5>
    <urn:graphragprov:unit:u_d61c19ce0a15a183>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
ORDER BY ?graph ?subject ?predicate ?object
